1	import React from 'react'
2	
3	export type CustomOptionProps = {
4	  onChange: (value: string) => void
5	  onCancel: () => void
6	  search?: string
7	}
8	
9	export type FilterOptionObject = {
10	  label: string
11	  value: string
12	}
13	
14	export type CustomOptionObject = {
15	  label?: string
16	  component: (props: CustomOptionProps) => React.ReactElement
17	}
18	
19	export type FilterOption = string | FilterOptionObject | CustomOptionObject
20	
21	export type AsyncOptionsFunction = (search?: string) => Promise<(string | FilterOptionObject)[]>
22	export type SyncOptionsFunction = (search?: string) => (string | FilterOptionObject)[]
23	
24	export type FilterProperty = {
25	  label: string
26	  name: string
27	  type: 'string' | 'number' | 'date' | 'boolean'
28	  options?: FilterOption[] | AsyncOptionsFunction | SyncOptionsFunction | CustomOptionObject
29	  operators?: string[]
30	}
31	
32	export type FilterCondition = {
33	  propertyName: string
34	  value: string | number | null
35	  operator: string
36	}
37	
38	export type FilterGroup = {
39	  logicalOperator: 'AND' | 'OR'
40	  conditions: (FilterCondition | FilterGroup)[]
41	}
42	
43	export function isGroup(condition: FilterCondition | FilterGroup): condition is FilterGroup {
44	  return 'logicalOperator' in condition
45	}
