5	type FilterConditionProps = {
6	  condition: FilterConditionType
7	  filterProperties: FilterProperty[]
8	  id: string
9	  isActive: boolean
10	  isOperatorActive: boolean
11	  isLoading?: boolean
12	  onOperatorChange: (value: string) => void
13	  onValueChange: (value: string) => void
14	  onOperatorFocus: () => void
15	  onValueFocus: () => void
16	  onBlur: () => void
17	  onLabelClick: () => void
18	  onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void
19	}
20	
21	export function FilterCondition({
22	  condition,
23	  filterProperties,
24	  id,
25	  isActive,
26	  isOperatorActive,
27	  isLoading,
28	  onOperatorChange,
29	  onValueChange,
30	  onOperatorFocus,
31	  onValueFocus,
32	  onBlur,
33	  onLabelClick,
34	  onKeyDown,
35	}: FilterConditionProps) {
36	  const operatorRef = useRef<HTMLInputElement>(null)
37	  const valueRef = useRef<HTMLInputElement>(null)
38	  const property = filterProperties.find((p) => p.name === condition.propertyName)
39	
40	  useEffect(() => {
41	    if (isActive && valueRef.current) {
42	      valueRef.current.focus()
43	    } else if (isOperatorActive && operatorRef.current) {
44	      operatorRef.current.focus()
45	    }
46	  }, [isActive, isOperatorActive])
47	
48	  if (!property) return null
49	
50	  return (
51	    <div className="flex items-center rounded px-2 h-6 bg-surface-400">
52	      <span className="text-xs font-medium mr-1 font-mono cursor-pointer" onClick={onLabelClick}>
53	        {property.label}
54	      </span>
55	      <Input_Shadcn_
56	        ref={operatorRef}
57	        value={condition.operator}
58	        onChange={(e) => onOperatorChange(e.target.value)}
59	        onFocus={onOperatorFocus}
60	        onBlur={onBlur}
61	        className="border-none bg-transparent p-0 text-xs focus:outline-none focus:ring-0 focus:shadow-none focus-visible:ring-0 focus-visible:ring-offset-0 font-mono h-6 mr-1 text-foreground-light"
62	        style={{
63	          width: `${Math.max(condition.operator.length, 1)}ch`,
64	          minWidth: '1ch',
65	        }}
66	        disabled={isLoading}
67	        aria-label={`Operator for ${property.label}`}
68	      />
69	      <Input_Shadcn_
70	        ref={valueRef}
71	        value={(condition.value ?? '').toString()}
72	        onChange={(e) => onValueChange(e.target.value)}
73	        onFocus={onValueFocus}
74	        onBlur={onBlur}
75	        onKeyDown={onKeyDown}
76	        className="border-none bg-transparent p-0 text-xs focus:outline-none focus:ring-0 focus:shadow-none focus-visible:ring-0 focus-visible:ring-offset-0 font-mono h-6"
77	        style={{
78	          width: `${Math.max((condition.value ?? '').toString().length, 1)}ch`,
79	          minWidth: '1ch',
80	        }}
81	        disabled={isLoading}
82	        aria-label={`Value for ${property.label}`}
83	      />
84	    </div>
85	  )
86	}
